           formStatus.textContent = "";

           const errors = Object.keys(fields).map((fieldName) => ({
             fieldName,
             message: validateField(fieldName)
           }));

           const firstError = errors.find((entry) => entry.message);

           if (firstError) {
             fields[firstError.fieldName].focus();
             formStatus.textContent = "Please correct the highlighted fields and submit again.";
             return;
           }

           formStatus.textContent = "Your message is ready to send.";
           form.reset();
           Object.keys(fields).forEach((fieldName) => setFieldError(fieldName, ""));
         });
       }

       mountApp();
